-- V30__exercise_description_en.sql
-- Thêm cột description_en cho bảng exercises, chuẩn hoá tên tiếng Việt cho các bài đang mang tên tiếng Anh,
-- và điền mô tả tiếng Anh chuẩn thể hình cho toàn bộ 164 bài tập.

-- Một số CSDL dev đã được nạp tay cột này trước khi Flyway ghi nhận V30;
-- kiểm tra information_schema để migration chạy lại an toàn, không lỗi "Duplicate column".
SET @has_description_en := (
    SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exercises' AND COLUMN_NAME = 'description_en'
);
SET @ddl := IF(@has_description_en = 0,
    'ALTER TABLE exercises ADD COLUMN description_en TEXT NULL AFTER description',
    'SELECT 1');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

